INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82547, 'spa', 'Eliel — nombre personal teofórico que significa ''mi Dios es Dios'' o ''Dios es mi ', 'Eliel — nombre personal teofórico que significa ''mi Dios es Dios'' o ''Dios es mi Dios'', llevado por múltiples individuos concentrados en los libros de Crónicas. Entre ellos se encuentran un jefe manasita (1 Cr 5:24), cabezas de familias benjaminitas (1 Cr 8:20, 22), guerreros entre la élite de David (1 Cr 11:46-47; 12:12) y levitas que asistieron en el traslado del arca (1 Cr 15:9, 11). La frecuencia del nombre en las genealogías postexílicas refleja la piedad teofórica renovada tras el destierro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82551, 'spa', 'Nombre propio Eliada', 'El nombre personal Eliada, ''Dios sabe''. Un hijo de David lleva este nombre (2 S 5:16; 1 Cr 3:8), con la forma alternativa Beeliada en 1 Cr 14:7, una sustitución reveladora donde בַּעַל (''señor/amo'') reemplaza a אֵל (''Dios''), probablemente por la aversión editorial posterior al título divino Baal. También lo portan el padre de Rezón, oponente de Salomón (1 R 11:23), y un capitán benjaminita al mando de tropas bajo Josafat (2 Cr 17:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82552, 'spa', 'Cola grasa sacrificial', 'La cola grasa de la oveja de cola ancha (Ovis laticaudata), especificada en la legislación sacrificial como porción dedicada a la ofrenda. Cada aparición empareja este término con חֵלֶב (''grasa''), distinguiendo la grasa de la cola como un corte separado y nombrado en el ritual sacerdotal de Éxodo 29 y Levítico 3, 7, 8 y 9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82553, 'spa', 'El nombre propio Elías, llevado principalmente por el gran profeta del siglo IX ', 'El nombre propio Elías, llevado principalmente por el gran profeta del siglo IX que declaró sequía (1 R 17:1), fue alimentado por cuervos y por una viuda, triunfó en el Carmelo (1 R 18:36-39) y ascendió en un torbellino (2 R 2:11). También se aplica a un benjaminita y a dos hombres de la época de Esdras, pero las traducciones interlingüísticas — español Elías, francés Élie, alemán Elia — los tratan uniformemente como un único sentido de nombre propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82558, 'spa', 'Elihú hijo de Baraquel el buzita, el joven que habla en Job 32-37 después de que', 'Elihú hijo de Baraquel el buzita, el joven que habla en Job 32-37 después de que los tres amigos mayores agotan sus argumentos. Airado con Job por su autojustificación y con los amigos por sus respuestas inadecuadas (Job 32:2-6), sus cuatro discursos sostienen que Dios usa el sufrimiento como disciplina y revelación, preparando el terreno para la teofanía divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82563, 'spa', 'Elyoenai (nombre propio)', 'Nombre propio Elyoenai (que significa ''mis ojos están hacia Dios''), que designa a varios individuos en genealogías y registros postexílicos: un descendiente davídico en 1 Crónicas 3:23-24, un líder simeonita en 4:36, un benjaminita en 7:8, y sacerdotes o retornados en Esdras 10:22, 10:27 y Nehemías 12:41. La variante Elyoenay refleja la variación ortográfica normal del hebreo tardío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82568, 'spa', 'Un idolo concreto o deidad falsa, un objeto de culto pagano considerado con desp', 'Un idolo concreto o deidad falsa, un objeto de culto pagano considerado con desprecio como un ''dios-nada''. El Codigo de Santidad prohibe volverse a los elilim (Lev 19:4; 26:1); los Salmos declaran que todos los dioses de los pueblos son elilim (Sal 96:5; 97:7). Los oraculos de Isaias contra la idolatria usan el termino repetidamente (Isa 2:8, 18, 20; 10:10-11; 19:1, 3; 31:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82574, 'spa', 'La cualidad abstracta de inutilidad, vanidad o insuficiencia', 'La cualidad abstracta de inutilidad, vanidad o insuficiencia. Zacarias 11:17 condena al ''pastor de nulidad'' (roeh ha-elil); Job 13:4 descarta a sus amigos como ''medicos de nulidad'' (rof''e elil); Jeremias 14:14 describe la falsa profecia como ''adivinacion vana''. Aqui el termino funciona como adjetivo o sustantivo abstracto mas que como designacion de una deidad extranjera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82582, 'spa', 'Elimélec', 'Elimélec (אֱלִימֶלֶךְ, ''Dios es rey''), esposo de Noemí en el libro de Rut. Abandona Belén durante una hambruna y se establece en Moab, donde muere, desencadenando los eventos que traen a Rut a la comunidad del pacto (Rut 1:2-3). Su propiedad y legado se vuelven centrales en la narrativa del pariente redentor (Rut 2:1, 3; 4:3, 9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82584, 'spa', 'Demostrativo plural arameo', 'Pronombre demostrativo plural arameo que significa ''estos/estas'', funcionando como el plural de דְּנָה. Se usa en Daniel para referirse a entidades previamente mencionadas: ''todos estos reinos'' (Dn 2:40, 44), ''estos sátrapas'' (Dn 6:2, 6) y ''estas bestias'' (Dn 7:17). Es cognado del palmireno אלן y del targúmico אלין, y forma parte del sistema demostrativo arameo estándar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82585, 'spa', 'Eliasaf', 'Eliasaf (אֶלְיָסָף, ''Dios ha añadido''), nombre propio de dos líderes del desierto. El más mencionado es el hijo de Deuel, jefe tribal de Gad, presente en el censo (Nm 1:14), el campamento (Nm 2:14) y las ofrendas del tabernáculo (Nm 7:42, 47). El segundo es el hijo de Lael, cabeza de los levitas gersonitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82586, 'spa', 'Eliezer (nombre propio) — Nombre propio hebreo (אֱלִיעֶזֶר, ''mi Dios es ayuda'') ', 'Eliezer (nombre propio) — Nombre propio hebreo (אֱלִיעֶזֶר, ''mi Dios es ayuda'') aplicado a al menos ocho figuras bíblicas distintas. Las traducciones interlingüísticas son estables (esp: Eliezer, fra: Éliézer, deu: Elieser), reflejando la práctica estándar de transliteración. El significado teológico del nombre, que invoca a Dios como ayudador, resuena especialmente en el nombramiento del hijo de Moisés (Éx 18:4, ''el Dios de mi padre fue mi ayuda'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82592, 'spa', 'Elifaz (nombre propio) — Nombre propio hebreo (אֱלִיפַז, posiblemente ''Dios es o', 'Elifaz (nombre propio) — Nombre propio hebreo (אֱלִיפַז, posiblemente ''Dios es oro fino'') llevado por dos figuras: (1) primogénito de Esaú con Ada, progenitor de clanes edomitas incluyendo Temán (Gn 36:4, 10-16; 1 Cr 1:35-36); y (2) Elifaz el temanita, principal consejero de Job que habla primero en cada ciclo de diálogos (Job 4:1; 15:1; 22:1) y es reprendido por Dios (Job 42:7, 9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82597, 'spa', 'Elifelet (nombre propio)', 'El nombre propio Elifelet (אֱלִיפֶלֶט), compuesto teofórico que significa «mi Dios es liberación». Lo llevaron un hijo de David (2 S 5:16; 1 Cr 3:6, 8; 14:7), uno de los guerreros de David (2 S 23:34), un benjaminita (1 Cr 8:39) y figuras postexílicas en Esdras 8:13 y 10:33. Las variantes ortográficas en los manuscritos reflejan la fluctuación escribal típica de los nombres propios compuestos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82600, 'spa', 'Elisur (nombre propio)', 'El nombre propio Elisur, que identifica al hijo de Sedeur y jefe tribal de Ruben. Su nombre, ''mi Dios es una roca'', pertenece a una familia de nombres compuestos con צוּר (cf. Tsuriel, Tsuri-sadai) que expresan confianza en la firmeza de Dios. Las cinco apariciones en Numeros lo situan en funciones tribales oficiales: el censo (1:5), la disposicion del campamento (2:10), las ofrendas de dedicacion del tabernaculo (7:30, 35) y el orden de marcha (10:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82601, 'spa', 'Elisafán (nombre propio)', 'Nombre propio teofórico que significa ''Dios ha protegido'' (de אֵל + צָפַן), designando al menos a dos individuos: (a) el jefe del clan coatita de los levitas, presente en el censo del desierto (Num 3:30), en la organización de músicos del templo por David (1 Cr 15:8) y en la purificación del templo bajo Ezequías (2 Cr 29:13); también escrito Elzafán en Éxodo 6:22 y Levítico 10:4; (b) un príncipe de la tribu de Zabulón encargado de repartir la tierra (Num 34:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82606, 'spa', 'Eliaquim (nombre propio) — Nombre propio hebreo (אֶלְיָקִים, ''Dios levanta''), re', 'Eliaquim (nombre propio) — Nombre propio hebreo (אֶלְיָקִים, ''Dios levanta''), referido al mayordomo del palacio de Ezequías durante la crisis asiria (2 R 18:18; Is 22:20; 36:3) y al nombre de nacimiento del rey Joacim (2 R 23:34; 2 Cr 36:4). Las traducciones al español (Eliaquim), francés (Elyakim) y alemán (Eljakim) conservan un solo nombre teofórico en todos los contextos sintácticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82610, 'spa', 'Nombre gentilicio', 'Génesis 10:4 y 1 Crónicas 1:7 enumeran a Elisá entre los hijos de Javán, nieto de Noé por línea de Jafet. Ezequiel 27:7 añade que «la púrpura de las costas de Elisá» cubría la cubierta de Tiro, un artículo de lujo asociado con la realeza. Los intérpretes antiguos propusieron la Hélade, Italia o Cartago; las propuestas modernas incluyen diversas regiones del Mediterráneo oriental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82612, 'spa', 'Nombre propio Eliasib (אֶלְיָשִׁיב, ''Dios restaura''), aplicado a al menos seis i', 'Nombre propio Eliasib (אֶלְיָשִׁיב, ''Dios restaura''), aplicado a al menos seis individuos distintos. Las transliteraciones interlingüisticas son notablemente estables (eng: Eliashib, spa: Eliasib, fra: Eliashib, deu: Eljaschib), reflejando una tradicion de transliteracion fija. El sumo sacerdote Eliasib domina la atestiguacion con 11 de 17 ocurrencias, todas concentradas en Esdras-Nehemias, donde encarna la tension entre restauracion y compromiso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82615, 'spa', 'El nombre propio Elisama (אֱלִישָׁמָע, ''Dios ha oído''), que designa a seis indiv', 'El nombre propio Elisama (אֱלִישָׁמָע, ''Dios ha oído''), que designa a seis individuos distintos en la Biblia hebrea. Las tradiciones de traducción son uniformes (esp: Elisama, fra: Élischama, deu: Elischama), lo que indica una transliteración bien establecida. El nombre aparece en Números (jefe efraimita), 2 Samuel y Crónicas (hijo de David), Jeremías (escriba real), 2 Reyes (linaje real).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82617, 'spa', 'El nombre propio del profeta Eliseo, sucesor de Elías', 'El nombre propio del profeta Eliseo, sucesor de Elías. Las 58 ocurrencias se encuentran dentro de 1-2 Reyes, refiriéndose al mismo individuo. Las traducciones — español ''Eliseo'', francés ''Élisée'', alemán ''Elisa'' — adaptan de distintas maneras el nombre teofórico, pero el significado subyacente ''Dios es salvación'' es universalmente reconocido. Su relato de llamamiento (1 R 19:16-19) y su petición de doble porción (2 R 2:9) lo establecen como heredero espiritual de Elías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82621, 'spa', 'Estos, aquellos (demostrativo) — Pronombre demostrativo plural arameo que signif', 'Estos, aquellos (demostrativo) — Pronombre demostrativo plural arameo que significa ''estos'' o ''aquellos'', que modifica sustantivos en las secciones arameas de Daniel y Esdras. Su colocación más frecuente es guvrāyyā'' illēk (''estos hombres'') en la narración del horno de Daniel 3 (vv. 12, 13, 21-23, 27) y el relato del foso de los leones de Daniel 6 (vv. 6, 12, 16, 25). En Esdras acompaña sustantivos administrativos en decretos del período persa (Esd 4:21; 5:9; 6:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82623, 'spa', 'Enmudecer, callar (Nifal)', 'Enmudecer, quedar mudo o en silencio (Nifal): la lengua «atada» de modo que el habla resulta imposible o se retiene deliberadamente. Las formas «enmudecí/enmudeció» y «estarás mudo» reflejan tanto el silencio voluntario (Sal 39:2, 9) como la mudez impuesta divinamente (Ez 3:26). La imagen del cordero silencioso de Isaías 53:7 —«no abrió su boca»— se convirtió en uno de los pasajes veterotestamentarios más citados en el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82625, 'spa', 'Ser enmudecido (Nifal yusivo)', 'Ser silenciado o enmudecido (Nifal yusivo/pasivo): una plegaria para que los labios mentirosos sean acallados por fuerza. El Salmo 31:18 emplea el yusivo «enmudezcan los labios mentirosos» (תֵּאָלַמְנָה), expresando el deseo de que el silencio sea impuesto. La fuerza pasiva distingue este sentido del silencio voluntario o profético del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82626, 'spa', 'Atar, liar (Piel)', 'Atar, amarrar (Piel): el significado raíz concreto y físico. Génesis 37:7 describe a José y sus hermanos «atando gavillas» (מְאַלְּמִים אֲלֻמִּים) en el campo, la escena onírica que pone en marcha toda la narrativa de José. Este sentido físico de atar contrasta vivamente con la «atadura» metafórica de la lengua en el Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82632, 'spa', 'Mudo, sin habla', 'Describe el estado de incapacidad para hablar, ya sea como condición física (Éx 4:11; Sal 38:13; Pr 31:8, donde se aboga por quienes no pueden hablar por sí mismos) o como acusación figurada: de profetas negligentes comparados con perros que no ladran (Is 56:10), de la gozosa reversión cuando la lengua muda cante (Is 35:6) y de ídolos inertes que carecen inherentemente de voz (Hab 2:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82637, 'spa', 'Madera preciosa importada', '1 Reyes 10:11-12 describe la flota de Hiram trayendo madera de almug desde Ofir junto con oro. Salomón la transformó en balaustradas para el templo y el palacio, y en instrumentos musicales «como nunca se habían visto en la tierra de Judá». La variación almug/algum ilustra cómo los préstamos lingüísticos extranjeros a veces recibían grafías inconsistentes en hebreo. Se han propuesto identificaciones con sándalo rojo u otras maderas tropicales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82638, 'spa', 'Gavilla de grano', 'Manojo atado de tallos de grano cortados, una gavilla. En Genesis 37:7 el termino aparece cuatro veces en la narracion del sueno de Jose, donde las gavillas personifican la futura sumision de los hermanos. En el Salmo 126:6, las gavillas simbolizan la cosecha gozosa que sigue a una temporada de llanto, figurando el retorno del exilio babilonico. La evidencia multilingue (espanol ''gavilla'', aleman ''Garbe'', frances ''gerbe'') apunta uniformemente al sentido agricola concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82643, 'spa', 'Viuda o mujer que ha perdido a su esposo (55x), una de las personas vulnerables ', 'Viuda o mujer que ha perdido a su esposo (55x), una de las personas vulnerables paradigmáticas de la Torá. Gn 38:11 presenta a Tamar enviada a casa de su padre como אַלְמָנָה, y Éx 22:22 ordena a Israel no afligir a ninguna viuda ni huérfano. Las traducciones convergen universalmente en ''viuda/widow/veuve/Witwe''. El corpus legal y profético desarrolla una amplia teología de la defensa divina de las viudas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82654, 'spa', 'Un posible sustantivo homógrafo que significa ''palacio'' o ''fortaleza'' (1x) en Is', 'Un posible sustantivo homógrafo que significa ''palacio'' o ''fortaleza'' (1x) en Is 13:22, dentro del oráculo contra Babilonia. Las traducciones ''en sus palacios'' en español y ''in her fortresses'' en inglés sugieren que los traductores reconocieron un lexema distinto aquí, probablemente derivado de una raíz relacionada con el acadio almattu. El contexto de chacales aullando en edificios grandiosos y desolados apoya la interpretación arquitectónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82660, 'spa', 'Estado de viudez', 'El estado o condición de viudez, que abarca tanto el duelo personal como la disminución social. Los ''vestidos de viuda'' de Tamar (Gn 38:14, 19) funcionan como marcas visibles de su estatus marginal. La difícil expresión ''viudez de vida'' para las concubinas confinadas de David (2 S 20:3) capta un estado liminal: técnicamente vivas pero socialmente muertas. En Is 54:4 el término se vuelve metafórico: la Jerusalén personificada dejará de recordar el oprobio de su viudez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82661, 'spa', 'Designador indefinido', 'En Rut 4:1, Booz llama al pariente redentor más cercano dirigiéndose a él como «fulano», en lugar de por su nombre: una curiosa decisión narrativa que mantiene el foco en Booz mientras reconoce los requisitos legales. 1 Samuel 21:3 y 2 Reyes 6:8 usan la expresión para lugares innominados: «a tal y tal lugar». La construcción combina dos marcadores indefinidos, reforzando la vaguedad de forma deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82663, 'spa', 'Elnatán (nombre propio)', 'El nombre propio Elnatán (''Dios ha dado''), que identifica a dos o más individuos: (a) Elnatán hijo de Acbor, funcionario judío y abuelo del rey Joaquín (2 R 24:8), enviado a extraditar a Urías desde Egipto (Jer 26:22) y presente en la quema del rollo de Jeremías (Jer 36:12, 25); (b) tres líderes, posiblemente levitas, convocados por Esdras junto al río Ahavá antes del retorno a Jerusalén (Esd 8:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82671, 'spa', 'El nombre propio masculino Eleazar (''Dios ha ayudado''), que se refiere principal', 'El nombre propio masculino Eleazar (''Dios ha ayudado''), que se refiere principalmente al tercer hijo de Aarón, quien llegó a ser el segundo sumo sacerdote de Israel tras la muerte de Aarón en el monte Hor (Nm 20:25-28; Éx 6:23; Jos 14:1), y secundariamente a varias figuras posteriores: el guardián del arca (1 S 7:1), uno de los valientes de David (2 S 23:9; 1 Cr 11:12), levitas en el servicio del templo (1 Cr 23:21-22) y personajes postexílicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82678, 'spa', 'Elealé (toponimo)', 'El toponimo Elealé, una ciudad transjordana cercana a Hesbon. Asignada a Ruben tras la conquista (Nm 32:3, 37), aparece despues en los oraculos de Isaias y Jeremias contra Moab (Is 15:4; 16:9; Jer 48:34) como simbolo de las ciudades moabitas arrasadas. La transliteracion uniforme en diversas lenguas (espanol ''Elealé'', ingles ''Elealeh'') refleja su condicion de nombre propio sin traduccion semantica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82679, 'spa', 'Elasá (nombre propio)', 'Nombre propio teofórico que significa ''Dios ha hecho'' (de אֵל + עָשָׂה), llevado por cuatro individuos en la Biblia hebrea: (a) un descendiente de Judá en la genealogía de Sesán (1 Cr 2:39-40); (b) un descendiente benjamita del rey Saúl por medio de Jonatán (1 Cr 8:37; 9:43); (c) un sacerdote del linaje de Pasur que despidió a su mujer extranjera durante las reformas de Esdras (Esd 10:22); y (d) un hijo de Safán que sirvió como mensajero de Jeremías ante los exiliados (Jer 29:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82683, 'spa', 'Aprender o enseñar', 'Aprender o enseñar, según la forma verbal. En Qal significa aprender o familiarizarse: ''no sea que aprendas sus caminos'' (Pr 22:25), advirtiendo contra absorber las costumbres del iracundo. En Piel significa enseñar o instruir: la iniquidad ''enseña'' a la boca astucia (Job 15:5), Dios ''nos enseña'' por encima de los animales (Job 35:11), y Elihú promete ''te enseñaré sabiduría'' (Job 33:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82685, 'spa', 'Ganado, bueyes', 'Ganado vacuno o bueyes, bovinos domésticos empleados en la labranza y la ganadería. El plural אֲלָפִים aparece en las fórmulas de bendición y maldición de Deuteronomio: ''la cría de tus vacas'' (שְׁגַר אֲלָפֶיךָ) en paralelo con ''las crías de tu rebaño'' (Dt 7:13; 28:4, 18, 51). En Proverbios 14:4 la cosecha abundante viene por la fuerza de los bueyes. El Salmo 8:7 los sitúa bajo el dominio humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82687, 'spa', 'Clan, subdivisión tribal', 'Clan, grupo familiar o subdivisión tribal dentro de Israel, una unidad social menor que la tribu (שֵׁבֶט/מַטֶּה) pero mayor que la casa paterna (בֵּית אָב). En Jueces 6:15 Gedeón objeta: ''Mi clan (אַלְפִּי) es el más débil de Manasés.'' Este sentido de אֶלֶף como unidad social o militar es debatido por los estudiosos y puede afectar la lectura de cifras grandes en otras partes de la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82690, 'spa', 'mil (numeral cardinal)', 'El numeral cardinal ''mil'' (1.000) empleado en conteos, totales de censos, mediciones, cantidades monetarias y expresiones temporales (427 ocurrencias). Abraham recibe אֶלֶף piezas de plata en Gn 20:16; el censo del Éxodo cuenta miles de combatientes (Éx 12:37). El español mil, el francés mille y el alemán tausend lo vierten con transparencia. Aparece en singular, constructo y con preposiciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82691, 'spa', 'dos mil (dual)', 'La forma dual אַלְפַּיִם que significa específicamente ''dos mil'' (2.000), usada como cantidad numérica precisa (31 ocurrencias). Nm 4:36 cuenta dos mil setecientos levitas; Nm 35:5 mide dos mil codos de pastizal. El francés deux-mille y el alemán zwei-Tausend preservan la precisión dual, mientras la morfología hebrea (sufijo dual -áyim) marca esta forma como categoría gramatical diferenciada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82693, 'spa', 'miles, millares (gran número)', 'El plural אֲלָפִים que significa ''miles'' o ''millares'' como cifra redonda elevada, cantidad multiplicada o expresión de abundancia abrumadora (31 ocurrencias). Éx 20:6 promete la lealtad de Dios ''a miles'' de generaciones; Rebeca es bendecida para llegar a ser ''millares de millares'' (Gn 24:60). El español miles/millares y el francés milliers captan tanto el registro contable como el hiperbólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82695, 'spa', 'clan, subdivisión tribal', 'Una unidad social y militar --clan, división o contingente dentro de una tribu israelita-- distinta del numeral (18 ocurrencias). En Jue 6:15, Gedeón identifica su אֶלֶף como el más débil de Manasés, claramente refiriéndose a su clan, no a un número. Nm 1:16 y 10:4 emplean el término para subdivisiones tribales. Este sentido tiene profundas implicaciones exegéticas: algunos estudiosos proponen que muchas cifras veterotestamentarias contaban ''clanes'' en vez de ''miles''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82727, 'spa', 'Mil (numeral arameo)', 'El numero cardinal arameo ''mil'', usado en formas absoluta, enfatica y constructa. En Daniel 5:1 cuantifica a los invitados del banquete de Belsasar, mientras que en Daniel 7:10 el constructo repetido אֶלֶף אַלְפִים (''mil millares'') evoca la hueste angelica innumerable ante el Anciano de Dias. La convergencia del espanol ''mil'', el frances ''mille'' y el aleman ''tausend'' confirma la funcion puramente numerica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82729, 'spa', 'Nombre propio benjaminita', '1 Crónicas 8:11, 12 y 18 sitúan a Elpaal dentro de la genealogía benjaminita, identificándolo como padre de varios hijos que llegaron a ser cabezas de familia. La repetición de su nombre lo señala como un nodo significativo en el árbol genealógico, aunque nada sabemos de sus hechos personales. El probable significado del nombre —«Dios del hacer» o «Dios ha actuado»— encaja en el patrón de nombres hebreos que contienen afirmaciones teológicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82732, 'spa', 'Nombre propio teofórico que significa ''Dios ha adquirido/creado,'' referido a var', 'Nombre propio teofórico que significa ''Dios ha adquirido/creado,'' referido a varios individuos bíblicos. El Elcaná más prominente es el padre de Samuel, cuya compasión por la estéril Ana y su fiel adoración en Siló enmarcan el relato del nacimiento del último juez de Israel (1 S 1:1–2:11). Otros portadores incluyen un coraíta (Éx 6:24), múltiples levitas en las genealogías del Cronista y un oficial de la corte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82739, 'spa', 'No destruyas (yusivo)', 'Forma del yusivo Hifil negado אַל־תַּשְׁחֵת (''no destruyas''), de la raíz שָׁחַת que significa ''arruinar, corromper, destruir''. Las ocho apariciones se encuentran en los encabezados de los Salmos 57:1, 58:1, 59:1 y 75:1. Se entiende generalmente como el nombre de una melodía o indicación litúrgica, posiblemente aludiendo al clamor intercesor de Moisés: ''No destruyas a tu pueblo'' (Dt 9:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82741, 'spa', 'madre, progenitora', 'Progenitora femenina humana, que abarca la maternidad biológica, el rol social y extensiones figuradas. Las 217 ocurrencias van desde Eva como ''madre de todos los vivientes'' (Gn 3:20) hasta la instrucción proverbial (''no abandones la enseñanza de tu madre'', Pr 1:8) y el lamento (''sus madres'', Lm 2:12). El español madre, el francés mère, el alemán Mutter y el árabe umm preservan el mismo sentido familiar íntimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82765, 'spa', 'madre animal', 'La madre de un animal, usada exclusivamente en leyes de compasión. ''No cocerás el cabrito en la leche de su madre'' (Éx 23:19; 34:26; Dt 14:21) y ''si encuentras un nido de ave, dejarás ir a la madre'' (Dt 22:6-7). Estas tres ocurrencias excepcionales extienden la dignidad materna más allá de la esfera humana, fundamentando la ética israelita en el respeto al vínculo entre la madre y su cría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82786, 'spa', 'condicional: si', 'Uso condicional dominante (827 veces), introduciendo protasis con verbos en imperfecto o perfecto. Pasajes clave como Gn 4:7 (''si haces bien'') y Gn 13:16 (''si alguien pudiera contar el polvo'') muestran tanto condiciones reales como hipoteticas. La uniformidad interlingüistica confirma un sentido unico y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82788, 'spa', 'disyuntiva: o', 'Particula disyuntiva ''o'' (82 veces), presentando alternativas u opciones. Las construcciones pareadas אִם...אִם (''sea...o'') aparecen en Gn 24:21 y Gn 37:32, donde el hablante plantea dos posibilidades. El cognado arabe أَم sirve igualmente como disyuntiva, confirmando el pedigri semitico de este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82791, 'spa', 'interrogativa indirecta: si', 'Interrogativa indirecta ''si acaso'' (8 veces), introduciendo incertidumbre tras verbos de conocimiento o prueba. Ex 19:13 y Lv 27:26 muestran contextos donde el resultado es genuinamente desconocido para el hablante. Se solapa con lo condicional pero es sintacticamente distinto al subordinarse a verbos cognitivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82795, 'spa', 'interrogativa retorica', 'Marcador interrogativo retorico (3 veces), esperando una respuesta afirmativa o negativa contundente. Los matices ''¿acaso no?'' reflejan esta fuerza. Nm 17:13 y Job 6:13 muestran la particula presionando al oyente hacia una conclusion obvia, una extension pragmatica de lo condicional hacia la persuasion discursiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82798, 'spa', 'concesiva: aunque', 'Uso concesivo ''aunque'' o ''aun si'' (1 vez en 1 Sm 15:17), donde la condicion se concede en lugar de cuestionarse. La reprension de Samuel --''aunque eres pequeno ante tus propios ojos''-- reconoce la premisa pero la supera. Este uso raro tiene paralelo en el arabe إن con fuerza concesiva en la retorica clasica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82801, 'spa', 'aseverativa: ciertamente', 'Uso aseverativo ''ciertamente'' en formulas de juramento (1 vez en Gn 15:4), donde אִם porta una autoimprecacion implicita: ''si hago esto [que Dios me castigue]'', significando ''ciertamente no lo hare''. Este uso idiomatico en juramentos esta bien atestiguado en todas las lenguas semiticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82804, 'spa', 'condicional: si', 'Sentido condicional donde כִּי y אִם conservan cada una su fuerza independiente, introduciendo la prótasis de una cláusula hipotética (''si'', ''que si'', ''pues si''). Gn 32:26 (''No te soltaré si no [כִּי אִם] me bendices'') y Gn 32:28 (''pues has luchado con Dios y con los hombres'') muestran la partícula condicional en acción en la narrativa de Jacob en Peniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82805, 'spa', 'restrictiva: solo, excepto', 'Sentido restrictivo o exceptivo, generalmente tras una negación, que limita el alcance a una sola alternativa: ''solo, excepto, nada más que, a menos que''. Gn 39:6 (Potifar confió todo a José y ''de nada se preocupaba excepto [כִּי אִם] del pan que comía''), Gn 39:9 (''nada me ha vedado sino [כִּי אִם] a ti''). El francés seulement y el alemán nur codifican esta función restrictiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82808, 'spa', 'adversativa: sino, más bien', 'Sentido adversativo que introduce una cláusula contrastiva o correctiva, a menudo tras una negación precedente: ''sino, más bien, por el contrario''. Nm 10:30 (Hobab dice ''No iré, sino que [כִּי אִם] me iré a mi propia tierra''), 2 S 13:33 (''No piense mi señor que han muerto todos los hijos del rey, pues [כִּי אִם] solo Amnón ha muerto''). El alemán sondern y el español sino captan el giro contrastivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82820, 'spa', 'concesiva: aunque', 'Matiz concesivo: ''aunque, aun cuando'', que reconoce una condición que podría esperarse que impidiera la cláusula principal pero no lo hace. Is 10:22 (''pues aunque [כִּי אִם] tu pueblo Israel sea como la arena del mar, solo un remanente volverá'') empareja abundancia con restricción. El español aunque y el alemán obwohl captan esta fuerza concesiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82822, 'spa', 'aseverativa: ciertamente', 'Sentido aseverativo en fórmulas de juramento y declaraciones solemnes, que confiere certeza enfática: ''ciertamente, en verdad, sin duda''. 1 S 8:19 (''¡No! Sino que [כִּי אִם] tendremos un rey sobre nosotros''), 2 S 15:21 (''Ciertamente [כִּי אִם] dondequiera que esté mi señor el rey, allí estará tu siervo''), Jr 51:14 (''Ciertamente [כִּי אִם] te llenaré de hombres'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82833, 'spa', 'temporal: cuando', 'Sentido temporal (''cuando'') donde כִּי אִם introduce el momento o circunstancia bajo la cual algo ocurre. Gn 42:15 (''Por vida de Faraón, no saldréis de aquí si no es cuando [כִּי אִם] vuestro hermano menor venga acá'') emplea el compuesto en la frontera entre lo condicional y lo temporal, marcando el punto en el que se cumplirá la condición. El español cuando y el alemán dass apuntan a un encuadre temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82838, 'spa', 'Una sierva dentro de un hogar, usada tanto como designación social en contextos ', 'Una sierva dentro de un hogar, usada tanto como designación social en contextos legales (Éx 20:10; 21:20) como autoreferencia deferente de mujeres que se dirigen a superiores — Ana ante Yahvé (1 S 1:11), Abigaíl ante David (1 S 25:24). Las traducciones — español sierva, francés servante, alemán Magd — reflejan este único rango semántico a lo largo de las 56 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82865, 'spa', 'codo (unidad de longitud)', 'El codo como unidad estándar de medida lineal, aproximadamente 45 cm o 18 pulgadas, el sentido casi universal con 246 ocurrencias. Se emplea para dimensiones de edificios (templo, tabernáculo, murallas), objetos (altar, arca de la alianza, asta de la lanza de Goliat), profundidades de agua (Gn 7:20) y distancias. Todas las lenguas lo vierten con un término de medición dedicado: español codo, francés coudée, alemán Elle.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82881, 'spa', 'medida (sentido metonímico)', 'Extensión metonímica a ''medida'' o ''patrón de medida'' en sentido amplio, con una sola ocurrencia en Jr 51:13 (''tú que moras junto a muchas aguas, abundante en tesoros, tu אַמָּה ha llegado''). Aquí la palabra parece significar algo como ''tu medida señalada'' o ''tu fin'', funcionando figuradamente para el destino decretado de Babilonia. El francés vierte vers y el alemán Mass, revelando la incertidumbre interpretativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82882, 'spa', 'codo-de (estándar específico)', 'El codo en constructo con un estándar especificador, con una sola ocurrencia en Dt 3:11, donde la cama de hierro de Og se mide por ''el codo de un hombre'' (אַמַּת אִישׁ), distinguiendo el codo ordinario de un posible codo real o largo (cf. Ez 40:5, donde se especifica un codo más un palmo menor). La frase en constructo funciona no como medida en sí sino como cláusula de calibración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82886, 'spa', 'Medida lineal', 'El codo arameo como unidad de medida lineal. La colosal imagen de oro de Nabucodonosor medía sesenta codos de altura y seis de anchura (Dn 3:1), proporciones que acentúan su imponente esbeltez. El decreto de Ciro para el templo de Jerusalén establece igualmente sesenta codos de alto y de ancho (Esd 6:3). En español se traduce directamente como ''codos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82888, 'spa', 'Tribus y pueblos', 'En Génesis 25:16 los doce hijos de Ismael se describen como «sus tribus y sus campamentos», organizados en unidades sociales coherentes. Números 25:15 identifica a una mujer madianita por su padre, «jefe del pueblo de una casa paterna en Madián». El Salmo 117:1 llama a «todos los pueblos» a alabar al Señor en paralelo con «todas las naciones», ampliando el término a un alcance universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82889, 'spa', 'Nación, pueblo', 'Sustantivo femenino אֻמָּה que significa ''nación, pueblo, tribu'', usado en hebreo bíblico tardío (Sal 117:1) y especialmente en arameo bíblico (Daniel y Esdras). En Daniel aparece en la fórmula estereotipada de corte ''pueblos, naciones y lenguas'' (אֻמַּיָּא, Dn 3:4, 7, 29; 4:1; 5:19; 6:26; 7:14), enfatizando el alcance universal de los decretos reales y la soberanía divina. Esdras 4:10 lo usa para referirse a grupos étnicos deportados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82893, 'spa', 'El nombre propio Amón (אָמוֹן), aplicado a tres figuras distintas', 'El nombre propio Amón (אָמוֹן), aplicado a tres figuras distintas: principalmente el rey idólatra de Judá que continuó los pecados de su padre Manasés y fue asesinado (2 R 21:19-26), también un gobernador de ciudad en tiempos de Acab (1 R 22:26), y un antepasado de los que regresaron del exilio (Neh 7:59). Las transliteraciones en las distintas lenguas son estables (esp: Amón, fra: Amon, deu: Amon).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82896, 'spa', 'Fidelidad, confiabilidad', 'Confiabilidad y fidelidad como cualidad moral, describiendo a personas o conductas en las que se puede confiar. En Deuteronomio 32:20, su ausencia (''no hay אֵמוּן en ellos'') acusa la infidelidad de Israel. Proverbios lo aplica como cualificativo para mensajeros (13:17), testigos (14:5) e individuos (20:6), mientras que Isaias 26:2 lo convierte en el requisito de entrada a la ciudad justa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82897, 'spa', 'La cualidad de ser fiel, confiable y digno de confianza — el sentido dominante e', 'La cualidad de ser fiel, confiable y digno de confianza — el sentido dominante en 47 ocurrencias. Se usa de la fidelidad pactual de Dios (Dt 32:4; Sal 36:5) y de la integridad humana en el ejercicio de funciones (2 R 12:15; 1 Cr 9:22). Frecuentemente emparejada con chesed (''amor leal''). El francés ''fidélité'' y el español ''fidelidad/con-verdad'' captan esta confianza relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82911, 'spa', 'Fe o confianza personal dirigida hacia Dios, de manera distintiva en Habacuc 2', 'Fe o confianza personal dirigida hacia Dios, de manera distintiva en Habacuc 2:4: ''el justo por su fe vivirá''. La evidencia multilingüe apoya la distinción — el español ''por su fe'' (no ''fidelidad'') y las tres citas neotestamentarias (Ro 1:17; Gá 3:11; He 10:38) tratan esto como confianza ejercida, no meramente como confiabilidad poseída.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82920, 'spa', 'Firmeza o estabilidad física — el significado concreto y literal de la raíz', 'Firmeza o estabilidad física — el significado concreto y literal de la raíz. En Éxodo 17:12, Aarón y Hur sostienen las manos de Moisés para que estén firmes (emunah) hasta la puesta del sol. El español ''firmeza'', el hindi ''स्थिर'' y los equivalentes árabes lo traducen como estabilidad física en vez de fidelidad moral, marcando un límite semántico claro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82921, 'spa', 'Nombre propio Amoz (אָמוֹץ), que identifica exclusivamente al padre del profeta ', 'Nombre propio Amoz (אָמוֹץ), que identifica exclusivamente al padre del profeta Isaías. Se distingue del profeta Amós (en hebreo עָמוֹס, con grafía diferente). Las 13 apariciones se encuentran en la fórmula fija ''Isaías hijo de Amoz'': en encabezados proféticos (Isa 1:1; 2:1; 13:1; 20:2), referencias narrativas durante el reinado de Ezequías (2 Re 19:2, 20; 20:1; Isa 37:2, 21; 38:1) y en los pasajes del Cronista (2 Cr 26:22; 32:20, 32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82923, 'spa', 'Poderoso, fuerte, valiente', 'Denota fuerza formidable, poder o valor, aplicado a personas, conspiraciones y supremamente a Dios. Se usa de la conspiración de Absalón que se fortalecía (2 Sam 15:12), de la fuerza irresistible de Dios en sabiduría y poder (Job 9:4, 19), del agente asirio del juicio divino descrito como ''fuerte y poderoso'' (Is 28:2), del guerrero más valiente que huye aterrorizado en el día de Jehová (Am 2:16) y de Dios que despliega las estrellas sin que falte ninguna (Is 40:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82930, 'spa', 'Languidecer, marchitarse o desvanecerse — describe un proceso de pérdida de vita', 'Languidecer, marchitarse o desvanecerse — describe un proceso de pérdida de vitalidad, fertilidad o fuerza. Se usa predominantemente en el tronco Pual para la tierra, los cultivos y la naturaleza personificada bajo juicio: ''los campos de Hesbón languidecen'' (Is 16:8), la vid ''languidece'' (Is 24:7), e incluso las rivales de Ana ''desfallecen'' mientras ella es bendecida (1 S 2:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82935, 'spa', 'Estar débil o endeble, describiendo un estado establecido más que un proceso pro', 'Estar débil o endeble, describiendo un estado establecido más que un proceso progresivo. Aparece en el participio pasivo Qal en Ezequiel 16:30: ''¡Cuán débil es tu corazón!'' — una exclamación sobre el estado moral debilitado de Jerusalén. El cambio del Pual (proceso) al Qal pasivo (estado) es significativo: donde el sentido 1 describe el marchitarse en movimiento, este sentido capta el punto final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82943, 'spa', 'fiel, digno de confianza', 'Participio Nifal con valor adjetival: fiel, confiable, seguro, perdurable. Describe personas, promesas o instituciones como firmes y dignos de confianza. El pacto de Dios es ''fiel'' (Dt 7:9), Moisés es ''fiel en toda mi casa'' (Nm 12:7) y a David se le promete una ''casa firme'' (1 S 2:35). Español ''fiel'' y árabe أمين captan esta cualidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82944, 'spa', 'creer, aceptar como verdadero', 'Hifil: creer, aceptar como verdadero, dar crédito a un mensaje, persona o promesa divina. Es el sentido de asentimiento cognitivo, ejemplificado célebremente en Génesis 15:6, donde Abraham ''creyó al SEÑOR y le fue contado por justicia''. La evidencia multilingüe converge con fuerza: español ''creyó'', francés ''crut'', alemán ''glaubte'' y árabe آمَنَ apuntan todos a la convicción intelectual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82947, 'spa', 'ser confirmado, establecido', 'Verbo finito Nifal: ser confirmado, establecido o verificado. Un sentido eventivo, no estativo, que marca la transición de una promesa o palabra a realidad consumada. Los hermanos de José deben demostrar que sus palabras son ''confirmadas'' (Gn 42:20); la palabra de Dios sobre la casa de David ''será establecida'' (2 S 7:16; 1 Cr 17:23-24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82952, 'spa', 'confiar, depender de', 'Hifil con semántica de confianza o dependencia: depositar la confianza en alguien, depender de, apoyarse en. Se distingue del sentido 1 por enfatizar la dependencia personal más que el mero asentimiento intelectual. Job 4:18 y 15:15 declaran que Dios no ''confía'' ni en sus siervos. En Dt 28:66, la vida pende sin confianza alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82971, 'spa', 'ser criado, amamantado', 'Participio pasivo Qal y Nifal pasivo: los que han sido criados, amamantados o cargados, la contraparte pasiva del sentido de crianza. En Lamentaciones 4:5, los ''criados en escarlata'' (הָאֱמֻנִים) ahora están desamparados; en Isaías 60:4, las hijas serán ''llevadas'' al costado. Solo dos ocurrencias claras marcan este sentido como raro pero distintivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (82972, 'spa', 'nodriza, tutor, criador', 'Participio activo Qal: nodriza, tutor o padre adoptivo, alguien que sostiene y cría a un niño. Noemí fue criadora de Obed (Rt 4:16); la nodriza de Mefiboset lo cargó al huir (2 S 4:4); los tutores de los hijos de Acab son אֹמְנִים (2 R 10:1, 5). Árabe مُرَبِّي y coreano 양육자 convergen en este significado concreto de crianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83013, 'spa', 'Confiar y ser fiel', 'En Daniel 6:23 se dice que Daniel «confió en su Dios» y por ello fue rescatado de los leones. Daniel 6:4 lo describe como «fiel», sin que se hallara negligencia alguna en él. Daniel 2:45 declara que el sueño y su interpretación son «dignos de confianza», firmes y ciertos. El contexto arameo refleja el mundo bilingüe de Daniel, sirviendo a emperadores extranjeros mientras mantenía la fe hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83016, 'spa', 'Afirmación litúrgica y de pacto que significa ''en verdad,'' ''así sea'' o ''queda es', 'Afirmación litúrgica y de pacto que significa ''en verdad,'' ''así sea'' o ''queda establecido.'' En Deuteronomio 27:15-26, la congregación ratifica cada maldición del pacto con ''Amén,'' aceptando su fuerza vinculante. En las doxologías del Salterio (Sal 41:13, 72:19, 89:52, 106:48), el doble ''Amén, Amén'' cierra cada libro de los Salmos con una alabanza enfática. Números 5:22 usa el doble Amén en el juramento ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83025, 'spa', 'Nombre personal Amnón, que significa ''fiel'' o ''digno de confianza', 'Nombre personal Amnón, que significa ''fiel'' o ''digno de confianza.'' El portador principal es el primogénito de David, cuya agresión contra Tamar y asesinato por Absalón impulsan la crisis dinástica narrada en 2 Samuel 13. Se escribe Aminón en 2 S 13:20 y de forma defectiva en 1 Cr 3:1. Un segundo Amnón, menos conocido, aparece en las genealogías de Judá (1 Cr 4:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83029, 'spa', 'Verdaderamente, ciertamente', 'Adverbio enfático aseverativo que significa ''verdaderamente, ciertamente, en verdad'', usado para confirmar una afirmación o cuestionar una suposición. El uso sincero aparece en Rut 3:12 (la declaración solemne de Boaz) y 2 Re 19:17 (reconociendo las conquistas reales de Asiria). El uso irónico o disputativo predomina en Job: ''verdaderamente vosotros sois el pueblo'' (Job 12:2), ''de verdad sé que es así'' (Job 9:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83031, 'spa', 'De verdad, acaso', 'Adverbio interrogativo-enfatico que significa ''de verdad, ciertamente, acaso,'' derivado de אָמֵן con la terminacion adverbial -am. Se usa exclusivamente en preguntas que expresan asombro o incredulidad. Genesis 18:13 constituye el uso paradigmatico: la pregunta de Dios ante la duda de Sara. La misma fuerza retorica aparece en el desafio de Balac (Nm 22:37), la oracion de Salomon en el templo (1 R 8:27; 2 Cr 6:18) y en las confrontaciones del salmista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83032, 'spa', 'ser fuerte, ser valiente — El sentido estativo e imperativo del Qal', 'ser fuerte, ser valiente — El sentido estativo e imperativo del Qal: ser fuerte, ser valiente, cobrar ánimo. Casi siempre emparejado con חָזַק (''sé fuerte'') en las fórmulas de comisión de Deuteronomio y Josué (Dt 31:6-7, 23; Jos 1:6-7, 18). La exhortación se extiende al aliento comunitario de los Salmos: ''Espera en el SEÑOR; esfuérzate y cobra ánimo'' (Sal 27:14; 31:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83035, 'spa', 'fortalecerse, mostrar determinación — El sentido reflexivo del Hitpael', 'fortalecerse, mostrar determinación — El sentido reflexivo del Hitpael: fortalecerse a sí mismo, mostrar determinación o resolución personal. Rut ''estaba decidida'' a ir con Noemí, y nada podía disuadirla (Rut 1:18). Roboam ''se esforzó'' por subir a su carro y huir (1 R 12:18 / 2 Cr 10:18). La morfología reflexiva traslada la acción hacia adentro: es un fortalecimiento autodirigido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83037, 'spa', 'fortalecer, afirmar — El sentido causativo-positivo del Piel', 'fortalecer, afirmar — El sentido causativo-positivo del Piel: fortalecer, afirmar, animar a otra persona o cosa. Job recuerda a Elifaz que sus palabras alguna vez ''fortalecieron'' al que tropezaba y afirmaron las rodillas débiles (Job 4:4). A Moisés se le ordena ''animar'' a Josué para la tarea que le espera (Dt 3:28). Los obreros del templo ''repararon'' — literalmente, consolidaron — la casa de Dios (2 Cr 24:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83039, 'spa', 'resolverse, decidirse — Fortalecerse a sí mismo con énfasis en la resolución o d', 'resolverse, decidirse — Fortalecerse a sí mismo con énfasis en la resolución o decisión firme, como en la determinación de Rut de acompañar a Noemí. El matiz recae en la voluntad deliberada más que en la fuerza física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83040, 'spa', 'endurecer, hacer obstinado — El Piel con coloración negativa', 'endurecer, hacer obstinado — El Piel con coloración negativa: endurecer, hacer obstinado. En Dt 2:30 Dios ''endureció'' el espíritu de Sijón; en Dt 15:7 se advierte a Israel que no ''endurezca'' el corazón contra el hermano pobre; en 2 Cr 36:13 Sedequías ''endureció'' su cerviz contra Dios. La misma raíz de fortalecimiento adquiere ahora un sentido de resistencia obstinada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83051, 'spa', 'apresurarse — Un uso marginal con matiz de urgencia o prisa, donde la energía in', 'apresurarse — Un uso marginal con matiz de urgencia o prisa, donde la energía interior se manifiesta en acción rápida y decidida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83065, 'spa', 'Amasías (nombre propio) — Nombre propio masculino אֲמַצְיָה/אֲמַצְיָהוּ (''Yah es', 'Amasías (nombre propio) — Nombre propio masculino אֲמַצְיָה/אֲמַצְיָהוּ (''Yah es poderoso''), que identifica principalmente al rey de Judá que reinó ca. 796-767 a.C. Su narrativa domina 2 Reyes 14 y 2 Crónicas 25: fidelidad inicial, victoria sobre Edom, luego soberbia que provoca la guerra con Joás de Israel, seguida de derrota y eventual asesinato (2 R 14:19; 2 Cr 25:27). El nombre también identifica al sacerdote de Betel que se enfrentó a Amós e intentó silenciar su profecía (Am 7:10, 12, 14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83071, 'spa', 'decir, hablar, contar', 'Sentido basico del Qal que abarca la comunicacion verbal en todas sus formas: decir, hablar, contar, mandar, responder e introducir discurso tanto directo como indirecto. Con mas de 5.290 apariciones, es el verbo narrativo de habla por defecto desde Gn 1:3 (''y dijo Dios'') en adelante. Toda lengua receptora lo traduce por su verbo de habla mas comun.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83109, 'spa', 'decirse, pensar', 'Uso interiorizado de אָמַר donde el ''decir'' se dirige a uno mismo en vez de a otra persona: pensar, resolver o deliberar en silencio. A menudo marcado por la frase בְּלִבִּי (''en mi corazon'') o por un contexto que hace inverosimil el habla externa. Ejemplos incluyen Gn 24:14 donde el siervo de Abraham idea una prueba internamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83122, 'spa', 'declarar, proclamar', 'Forma Hifil y uso enfatico del Qal donde אָמַר significa declarar publicamente, proclamar o anunciar formalmente: un acto de habla que conlleva autoridad o solemnidad mas alla de la conversacion ordinaria. Dt 26:17 usa el Hifil: Israel ''declaro'' (הֶאֱמַרְתָּ) que el SENOR era su Dios. Sal 40:10 y 45:1 presentan igualmente proclamacion publica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83131, 'spa', 'El sentido básico y abrumadoramente dominante de comunicación verbal — decir, ha', 'El sentido básico y abrumadoramente dominante de comunicación verbal — decir, hablar, contar o declarar. Abarca el habla ordinaria, las respuestas en diálogos (''respondió y dijo'', Dn 2:7), la transmisión de información (Esd 5:3-4, 9) y la interpretación profética (Dn 2:25-26). El español ''dijo/decía'', el francés ''dit'' y el alemán ''sprach'' traducen este acto comunicativo directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83133, 'spa', 'El sentido autoritativo de mandar, ordenar o emitir una directiva real', 'El sentido autoritativo de mandar, ordenar o emitir una directiva real. Cuando Nabucodonosor ''amar'' que los astrólogos sean destruidos (Dn 2:12), o que el horno se caliente siete veces más (Dn 3:19), o cuando Belsasar ''amar'' que traigan los vasos de oro (Dn 5:2), el contexto eleva el habla simple a mandato soberano. El español ''ordenó'' marca claramente esta distinción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83137, 'spa', 'El uso pasivo o impersonal donde el verbo significa ''ser dicho'', ''ser proclamado', 'El uso pasivo o impersonal donde el verbo significa ''ser dicho'', ''ser proclamado'' o ''ser llamado''. En Dn 3:4 un heraldo proclama ''a vosotros se os dice'' (o ''se os manda''), y Dn 4:31 usa una construcción impersonal similar para una voz del cielo. Este sentido elimina el sujeto personal y presenta el habla como un anuncio autoritativo — algo declarado a todos más que dicho por alguien en particular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83151, 'spa', 'Palabras, dichos, expresiones — contenido hablado en discurso poético o elevado,', 'Palabras, dichos, expresiones — contenido hablado en discurso poético o elevado, frecuentemente en plural. Abarca el habla humana (Job 6:26; 32:12-14), las enseñanzas de los sabios (Pr 2:1; 4:10, 20; 7:1), los oráculos de Balaam (Nm 24:4, 16) y las palabras de Dios (Sal 107:11; Jos 24:27). El francés ''paroles'' y el español ''palabras/dichos'' confirman el sentido general de habla a lo largo de 48 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83167, 'spa', 'Decreto o palabra autoritativa — un pronunciamiento singular y vinculante que en', 'Decreto o palabra autoritativa — un pronunciamiento singular y vinculante que enfatiza la determinación divina más que la conversación. En Job 20:29, Zofar declara que esta es ''la porción del hombre impío de parte de Dios, la herencia que le ha sido decretada''. El español traduce ''su palabra'' (su palabra/decreto) y el francés ''son parole'', ambos marcando el carácter singular y solemne que lo distingue del habla ordinaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83172, 'spa', 'Palabra, discurso', 'Sustantivo poético masculino que significa ''palabra, discurso, declaración'', funcionando como sinónimo elevado de דָּבָר. Se encuentra predominantemente en la literatura sapiencial y poética: del ''habla'' sin palabras de la creación que proclama la gloria de Dios (Sal 19:2-3), de la promesa firme de Dios cuestionada en el lamento (Sal 77:8), de los decretos del justo que se establecen (Job 22:28) y de la ''palabra'' que Dios dio a la gran compañía de proclamadores (Sal 68:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83175, 'spa', 'Corderos sacrificiales', 'Esdras 6:9 ordena que se provean corderos diariamente para holocaustos al Dios del cielo, financiados por el tesoro real. Esdras 6:17 describe la ceremonia de dedicación donde se ofrecieron corderos como ofrendas por el pecado en representación de las doce tribus. Esdras 7:17 destina fondos reales para adquirir corderos para los sacrificios del templo, subrayando la centralidad de estas ofrendas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83176, 'spa', 'Nombre de familia sacerdotal que se remonta al decimosexto de los veinticuatro t', 'Nombre de familia sacerdotal que se remonta al decimosexto de los veinticuatro turnos sacerdotales de David (1 Cr 24:14). Pasur hijo de Imer sirvió como oficial principal del templo y se enfrentó con Jeremías (Jer 20:1). La familia regresó del exilio en gran número —1.052 hombres (Esd 2:37; Neh 7:40)— y algunos estuvieron implicados en la controversia de las esposas extranjeras (Esd 10:20). El nombre también aparece como una localidad de ubicación incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83179, 'spa', 'palabra o promesa divina — La palabra, dicho o promesa de Dios, dirigida directa', 'palabra o promesa divina — La palabra, dicho o promesa de Dios, dirigida directamente en oración o alabanza como objeto de devoción y confianza. Este sentido dominante (22 ocurrencias) se concentra abrumadoramente en el Salmo 119, donde el salmista atesora ''tu palabra'' en su corazón (119:11), pide a Dios que confirme su promesa (119:38) y espera en la palabra de Dios (119:41, 50, 58, 76, 82, 116, 140, 148, 158, 162, 170, 172).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83181, 'spa', 'palabra o dicho (general) — Palabra o dicho en general, usado en estado construc', 'palabra o dicho (general) — Palabra o dicho en general, usado en estado constructo (''la palabra de'', ''el dicho de'') sin especificar si la fuente es divina o humana, y frecuentemente funcionando como cuasi-sinónimo de דָּבָר en paralelismo poético. Siete ocurrencias llevan este sentido puente: ''la palabra del SEÑOR es probada'' (2 S 22:31; Sal 18:30), ''las palabras del SEÑOR son palabras puras'' (Sal 12:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83183, 'spa', 'discurso o dicho (humano) — Discurso o dicho humano', 'discurso o dicho (humano) — Discurso o dicho humano: las propias palabras de una persona vistas como declaración, discurso o enseñanza. Siete ocurrencias marcan este referente específicamente humano: el desafiante ''oíd mi dicho'' de Lamec (Gn 4:23), la comparación de Moisés de su enseñanza con la lluvia y el rocío (Dt 32:2), y la súplica del salmista ''da oído a mis palabras'' (Sal 17:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83196, 'spa', 'Un sustantivo gentilicio propio que designa a los amorreos, un importante pueblo', 'Un sustantivo gentilicio propio que designa a los amorreos, un importante pueblo cananeo que habitaba la región montañosa a ambos lados del Jordán. Llamados ''hijo de Canaán'' en la Tabla de las Naciones (Gn 10:16), son más prominentes en las narrativas de la conquista como gobernantes de Transjordania (Nm 21:13; Dt 3:9). El uso casi universal del término con artículo lo marca como designación étnica colectiva más que como nombre individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83213, 'spa', 'El nombre propio Amarías/Amaryahu (אֲמַרְיָה/אֲמַרְיָהוּ, ''YHWH ha prometido''), ', 'El nombre propio Amarías/Amaryahu (אֲמַרְיָה/אֲמַרְיָהוּ, ''YHWH ha prometido''), que designa a múltiples figuras del AT: (1) un levita en la genealogía del sumo sacerdocio (1 Cr 6:7, 11, 52; Esd 7:3); (2) un levita coatita en tiempos de David (1 Cr 23:19; 24:23); (3) el sumo sacerdote bajo el rey Josafat (2 Cr 19:11); (4) un levita bajo Ezequías (2 Cr 31:15); (5) un antepasado del profeta Sofonías (Sof 1:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83217, 'spa', 'Ayer, anoche', 'Adverbio temporal que significa ''ayer'' o ''anoche,'' con extension ocasional al pasado reciente. La raiz puede estar relacionada con la palabra semitica para ''tarde'' (cf. arabe masa'', asirio mushu ''noche''), lo que explica su frecuente implicacion de la noche anterior. Genesis 19:34 y 31:29, 42 lo emplean para eventos de la noche previa, mientras que 2 Reyes 9:26 lo extiende al sentido de ''recientemente.'' Job 30:3 presenta dificultades textuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83218, 'spa', 'verdad, veracidad', 'Verdad como realidad factual, corrección o veracidad, el sentido dominante con 98 ocurrencias. Abarca afirmaciones de exactitud objetiva (''¿es verdad?''), discurso veraz (''palabras de verdad'') y la calificación de algo como genuino. En Gn 24:49 y 47:29, actuar ''en verdad'' significa con honestidad. En Éx 34:6, Dios es descrito como ''grande en verdad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83222, 'spa', 'fidelidad, fiabilidad', 'Fidelidad y lealtad como cualidad relacional, con 27 ocurrencias, frecuentemente con sufijos posesivos (''tu fidelidad'', ''su verdad'') que apuntan a un atributo personal. En Gn 24:27, el siervo de Abraham alaba a Dios que ''no ha dejado su חֶסֶד ni su אֱמֶת''; en Gn 32:10, Jacob confiesa ser indigno de la אֱמֶת de Dios. El sentido es de lealtad pactual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83229, 'spa', 'verdadero, genuino', 'Uso adjetival o calificativo: verdadero, genuino, auténtico, con solo dos ocurrencias (2 Cr 31:20; Dn 10:1). En 2 Cr 31:20, Ezequías hace lo ''bueno, recto y verdadero''; en Dn 10:1, la revelación es descrita como אֱמֶת, ''verdadera, auténtica''. Aquí אֱמֶת funciona atributivamente, modificando un sustantivo o en posición predicativa para certificar autenticidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83247, 'spa', 'Costal o saco grande para transportar grano, atestiguado exclusivamente en el ci', 'Costal o saco grande para transportar grano, atestiguado exclusivamente en el ciclo de José (Gn 42–44). Se distingue del hebreo común שַׂק; aparece en singular constructo (Gn 44:2, 12) y en plural con sufijos (Gn 43:18, 21-22). La frase בְּפִי אַמְתַּחַת (''en la boca del costal'') funciona como recurso narrativo: los hermanos descubren la plata escondida (Gn 42:27-28) y luego la copa plantada (Gn 44:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83258, 'spa', '¿dónde?, ¿adónde? (interrogativo) — Adverbio interrogativo de lugar que signific', '¿dónde?, ¿adónde? (interrogativo) — Adverbio interrogativo de lugar que significa ''¿dónde?'' o ''¿adónde?'', usado en preguntas directas sobre ubicación o dirección de movimiento. La pregunta del ángel a Agar en Gn 16:8 (''¿De dónde vienes y adónde vas?'') ejemplifica este uso espacial fundamental. También aparece en preguntas indirectas (Jos 2:5) y en interrogaciones retóricas cargadas de emoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83259, 'spa', '¿hasta cuándo? (interrogativo temporal) — Interrogativo temporal que significa ''', '¿hasta cuándo? (interrogativo temporal) — Interrogativo temporal que significa ''¿hasta cuándo?'' o ''¿por cuánto tiempo?'', formado con la preposición עַד (עַד־אָנָה). Este uso lleva un tono de exasperación o lamento: Dios mismo pregunta ''¿hasta cuándo me despreciará este pueblo?'' (Nm 14:11), y el salmista clama ''¿hasta cuándo, oh SEÑOR?'' (Sal 13:2). Se encuentra especialmente en pasajes de queja y reprensión profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83261, 'spa', 'a cualquier parte, de acá para allá (indefinido) — Adverbio locativo indefinido ', 'a cualquier parte, de acá para allá (indefinido) — Adverbio locativo indefinido que significa ''a cualquier parte'' o ''de acá para allá'', que aparece en la frase duplicada אָנֶה וָאָנָה. Salomón dice a Simei que no vaya ''a ningún lado'' fuera de Jerusalén (1 R 2:36, 42), y Giezi niega haber ido ''a parte alguna'' (2 R 5:25). La duplicación idiomática crea un indefinido a partir de un interrogativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83263, 'spa', '[variante ketiv] — Variante textual ketiv (escrita) en 2 R 5', '[variante ketiv] — Variante textual ketiv (escrita) en 2 R 5:25, donde el texto consonántico lee מֵאָן (''¿de dónde?'') con la preposición מ prefijada a אָן. La tradición qere (leída) normaliza esto de forma diferente. Los glosarios en todas las lenguas simplemente lo marcan como ''[ketiv]'', reflejando su condición de curiosidad escribal u ortográfica más que un sentido semántico distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83265, 'spa', 'Pronombre «yo»', 'En Esdras 6:12 el rey Darío declara «yo, Darío, he promulgado este decreto», estampando su autoridad personal sobre la orden de apoyar la reconstrucción del templo. Esdras 7:21 registra el decreto de Artajerjes: «yo decreto», discurso real en primera persona que asignó recursos para el culto en Jerusalén. Daniel 2:8 lo usa cuando el rey dice: «yo sé con certeza que estáis tratando de ganar tiempo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83266, 'spa', 'Pronombre personal independiente de primera persona singular en arameo, que func', 'Pronombre personal independiente de primera persona singular en arameo, que funciona como sujeto enfático o como refuerzo de un sufijo pronominal. Se usa en la autoidentificación real (''Yo, Nabucodonosor'', Dn 4:1, 15, 34), en la autorreferencia profética (''Yo estaba mirando'', Dn 4:7; ''Yo, Daniel'', Dn 7:15, 28) y en decretos oficiales (''Yo decreto'', Esd 7:21). Cognado del hebreo אֲנִי y del siríaco ܐܢܐ. Las 13 apariciones se encuentran en las porciones arameas de Daniel y Esdras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83268, 'spa', 'Partícula discursiva que expresa ruego ferviente o súplica, generalmente antes d', 'Partícula discursiva que expresa ruego ferviente o súplica, generalmente antes de una petición dirigida a Dios o a una persona de autoridad. Aparece en momentos de gran intensidad: Moisés confesando el pecado de Israel (Éx 32:31), Ezequías en su lecho de muerte (2 Re 20:3), Nehemías abriendo su oración (Neh 1:5, 11). Transmite una urgencia deferente, equivalente al español ''te ruego'' o ''por favor'' en tono solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83275, 'spa', 'Acontecer o sobrevenir', 'Acontecer, sobrevenir, alcanzar: describe un suceso que alcanza a alguien, a menudo con causalidad divina. En Éxodo 21:13 Dios ''hace acontecer'' una muerte no intencionada, mientras que Salmo 91:10 y Proverbios 12:21 usan la misma raíz para asegurar que ningún mal sobrevendrá al justo. La forma Hitpael en 2 Reyes 5:7 adquiere el matiz de buscar ocasión o provocar una querella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83277, 'spa', 'Ellos, aquellos', 'Esdras 5:4 pregunta «¿cuáles son los nombres de aquellos hombres que edifican este edificio?», donde «aquellos» identifica al grupo específico bajo investigación. Daniel 2:44 profetiza que Dios establecerá un reino «en los días de aquellos reyes», señalando a los reyes representados en la visión de Nabucodonosor. Daniel 6:24 dice que los leones dominaron «a ellos», los acusadores arrojados al foso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83279, 'spa', 'hombre, ser humano — Una persona humana individual, usada genérica o específicam', 'hombre, ser humano — Una persona humana individual, usada genérica o específicamente para referirse a un hombre o ser humano: el significado léxico básico que abarca la mayoría de las ocurrencias. Este sentido dominante (39 ocurrencias) aparece en las preguntas angustiadas de Job (''¿Acaso no es la vida del אֱנוֹשׁ un servicio forzado?'' Job 7:1), oráculos proféticos (Is 13:12; 56:2) y los Salmos (Sal 55:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83285, 'spa', 'humanidad, colectivo humano — Los seres humanos colectivamente', 'humanidad, colectivo humano — Los seres humanos colectivamente: la humanidad o el género humano como grupo, en vez de un individuo específico. Con 2 ocurrencias, este sentido colectivo aparece en Deuteronomio 32:26 (''Haré cesar de entre los hombres la memoria de ellos'') y Salmo 144:3 (''SEÑOR, ¿qué es el hombre para que lo tengas en cuenta?'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83286, 'spa', 'mortal, humano frágil — Un ser humano con énfasis en la mortalidad, debilidad y ', 'mortal, humano frágil — Un ser humano con énfasis en la mortalidad, debilidad y fragilidad: un uso retórico concentrado en contextos sapienciales y poéticos que resalta los límites de la naturaleza humana ante Dios. Una ocurrencia clara en Job 4:17, donde Elifaz pregunta ''¿Puede el mortal (אֱנוֹשׁ) ser justo delante de Dios?'' La conexión etimológica con la debilidad distingue este sentido del uso neutro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83289, 'spa', 'Enós (nombre propio)', 'El nombre propio Enós (que significa ''hombre, mortal''), designando al hijo de Set nacido cuando Adán tenía 235 años. Sus datos genealógicos abarcan Génesis 5:6-11 (nacimiento, paternidad de Cainán, vida de 905 años y muerte), y encabeza el linaje posterior a Set en 1 Crónicas 1:1. De modo notable, Génesis 4:26 asocia su nacimiento con el comienzo del culto público: «Entonces se comenzó a invocar el nombre de YHWH».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83291, 'spa', 'Emitir un gemido o suspiro audible que expresa dolor, pena o angustia', 'Emitir un gemido o suspiro audible que expresa dolor, pena o angustia. Abarca la mayoría de las apariciones, desde el gemido colectivo de Israel bajo la esclavitud egipcia (Éx 2:23) hasta el marchitarse del gozo en Isaías 24:7. Lamentaciones 1:4 y 1:8 lo usan para Jerusalén personificada como mujer que gime. Proverbios 29:2 lo vincula con la opresión nacional: cuando gobiernan los malvados, el pueblo gime.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83297, 'spa', 'Uso sustantivado con artículo definido para designar una categoría de personas', 'Uso sustantivado con artículo definido para designar una categoría de personas: ''los que gimen'', aquellos que suspiran y se lamentan por la corrupción moral. Se encuentra en Ezequiel 9:4, donde Dios ordena a un escriba marcar la frente de quienes ''gimen y claman'' por las abominaciones en Jerusalén. Esta única aparición transforma una acción verbal en una identidad que define a los justos dolientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83301, 'spa', 'Suspiro o gemido audible que surge del dolor, la aflicción o la angustia espirit', 'Suspiro o gemido audible que surge del dolor, la aflicción o la angustia espiritual. Job lo emplea para el lamento involuntario que reemplaza el sustento normal (Job 3:24; 23:2). Los Salmos lo convierten en sello distintivo del justo sufriente: el salmista se consume de tanto gemir (Sal 6:6; 31:10; 38:9; 102:5). Isaías lo empareja con el dolor como algo que desaparecerá en la restauración escatológica (Is 35:10; 51:11). Lamentaciones lo vincula con un corazón desfallecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83311, 'spa', 'Pronombre plural ''nosotros''', 'Pronombre de primera persona del plural ''nosotros'' en arameo bíblico, usado tanto en correspondencia oficial como en discurso directo dentro de las secciones arameas de las Escrituras. En Daniel 3:16-17, los tres exiliados fieles declaran ''no necesitamos responderte'', confiriendo al pronombre un tono de identidad comunitaria valiente. En Esdras 4:16 y 5:11 aparece en cartas diplomáticas formales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83312, 'spa', 'nosotros (pronombre plural)', 'El pronombre independiente de primera persona común plural ''nosotros'', empleado en hebreo bíblico cuando los hablantes desean hacer explícito el sujeto para énfasis, contraste o identificación. Aparece frecuentemente en declaraciones de autoidentificación: ''somos hermanos vuestros'' (Gn 42:13), ''estamos de paso'' (Jue 19:18), y puede seguir a participios o añadirse a verbos para dar peso retórico (Gn 19:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83317, 'spa', 'yo (primera persona)', 'Pronombre personal independiente de primera persona del singular, forma no marcada, empleado tanto por hablantes humanos como divinos para identificarse como sujeto del discurso. Se distingue de la forma más solemne אָנֹכִי (H0595) por ser la variante cotidiana en narrativa, poesía, profecía y literatura sapiencial. Su equivalencia interlingüística es máximamente uniforme: español yo, francés je, alemán ich.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83322, 'spa', 'Nave, flota de naves', 'Una nave o flota de naves, usada tanto como sustantivo singular para una embarcación individual como colectivamente para una flota naval. La forma constructa en 1 Reyes 9:26 y 10:11, 22 funciona como ''flota de'', describiendo la flota comercial de Salomón en el Mar Rojo, construida en Ezión-Guéber con ayuda fenicia (1 R 9:26-27), los viajes a Ofir trayendo oro (1 R 10:11) y las ''naves de Tarsis'' que regresaban trienalmente con cargamentos exóticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83326, 'spa', 'nave, embarcación marítima — Embarcación marítima usada para el comercio, expedi', 'nave, embarcación marítima — Embarcación marítima usada para el comercio, expediciones militares o transporte. Abarca la flota de Salomón hacia Ofir (1 R 9:26-28; 10:22), las naves naufragadas de Josafat (1 R 22:48) y el barco en que Jonás huye (Jon 1:3-5). Las imágenes proféticas emplean las naves como emblemas del orgullo comercial y la vulnerabilidad: las ''naves de Tarsis'' de Isaías (Is 2:16; 23:1, 14) y la alegoría de Ezequiel sobre Tiro (Ez 27:9, 25-29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83345, 'spa', 'Plomada de albañil', 'Plomada: cuerda lastrada con plomo usada para verificar la verticalidad en la construcción, empleada metafóricamente como estándar de justicia divina. En Amós 7:7-8 el término aparece cuatro veces en rápida sucesión: Dios muestra a Amós un muro edificado a plomada (חוֹמַת אֲנָךְ) y declara que pondrá una plomada en medio de Israel, midiendo su rectitud moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83346, 'spa', 'yo (pronombre enfático)', 'La forma enfática o solemne del pronombre independiente de primera persona singular (''yo''), usada junto a la más breve אֲנִי (H0589). Preferida en declaraciones formales, autoidentificación divina (Éx 20:2: ''Yo soy el SEÑOR tu Dios'') y discursos de carga emocional (Gn 3:10: ''tuve miedo''). Su cognado acadio anāku y su ausencia del arameo y el árabe apuntan a orígenes arcaicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83353, 'spa', 'Estar airado o disgustado en la conjugación Qal básica, expresando un estado de ', 'Estar airado o disgustado en la conjugación Qal básica, expresando un estado de ira o indignación divina. Se usa para el enojo de Dios ante la infidelidad de Israel (1 Re 8:46; 2 Cr 6:36; Esd 9:14) y en las preguntas urgentes del salmista sobre la duración del disgusto divino (Sal 79:5; 85:6). La célebre advertencia del Salmo 2:12 — ''no sea que se enoje y perezcáis'' — captura la terrible brevedad de esta forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83354, 'spa', 'Encenderse en ira o ser provocado a cólera en la conjugación Hitpael (reflexivo-', 'Encenderse en ira o ser provocado a cólera en la conjugación Hitpael (reflexivo-intensivo), enfatizando la erupción visible o la intensificación de la ira. Cada aparición en Hitpael lleva la preposición בְּ (''contra'') y se refiere a la ira de Dios ante provocaciones específicas: Moisés excluido de la tierra por el pecado de Israel (Dt 1:37; 4:21), la rebelión del becerro de oro (Dt 9:8, 20), la apostasía de Salomón (1 Re 11:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83366, 'spa', 'Gemir de angustia', 'Gemir o clamar de angustia: expresión gutural e involuntaria de dolor o duelo. Las formas Qal en Jeremías 51:52 y Ezequiel 26:15 describen el gemido de los heridos mortalmente (חָלָל), mientras que el Nifal en Ezequiel 24:17 se asocia con ritos fúnebres y en Ezequiel 9:4 con el suspirar (נֶאֱנָחִים) ante las abominaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83367, 'spa', 'Gemido angustiado', 'Gemido, clamor angustiado: el grito sostenido y lastimero del oprimido o encarcelado que asciende hasta Dios. En el Salmo 12:5 es el gemido del necesitado (אֶבְיוֹן) lo que mueve a Dios a actuar; en los Salmos 79:11 y 102:20 es el quejido del prisionero (אָסִיר) que alcanza el cielo. Malaquías 2:13 lo empareja con llanto y lágrimas (דִּמְעָה, בְּכִי) junto al altar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83369, 'spa', 'Incurable, irremediable', 'Incurable, irremediable, sin posibilidad de sanación, funcionando como adjetivo derivado del participio pasivo Qal. Describe heridas, enfermedades o dolores que no admiten remedio. Se usa metafóricamente para la condición espiritual de Judá (Jer 15:18; 30:12), de Samaria (Miq 1:9) y del corazón humano (Jer 17:9). El español lo traduce consistentemente como ''incurable''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83376, 'spa', 'Enfermó gravemente', 'Enfermó gravemente, de muerte — forma del imperfecto consecutivo Nifal (וַיֵּאָנַשׁ) que describe el inicio agudo de una enfermedad mortal. Atestiguada únicamente en 2 Samuel 12:15, donde el hijo de David y Betsabé es herido por el SEÑOR y ''enfermó''. A diferencia del sentido adjetival que describe una condición crónica e irremediable, esta forma verbal capta el momento preciso en que sobreviene la dolencia fatal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83377, 'spa', 'Un ser humano o la humanidad colectivamente, el equivalente arameo estándar del ', 'Un ser humano o la humanidad colectivamente, el equivalente arameo estándar del hebreo enosh. Se usa genéricamente para referirse a personas (Dn 2:10; 3:10; 6:12) y colectivamente para designar al género humano, como cuando Nabucodonosor es expulsado de la sociedad humana (Dn 4:25, 32-33; 5:21). La expresión compuesta bar enash en Daniel 7:13 se convirtió en fundamento de la teología mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83385, 'spa', 'Pronombre arameo bíblico de segunda persona masculino singular ''tú,'' usado en di', 'Pronombre arameo bíblico de segunda persona masculino singular ''tú,'' usado en discurso directo en Daniel y Esdras. La grafía ketiv אנתה conserva una forma más antigua, mientras que el qere lee la forma más corta אנת. Aparece en el discurso de Daniel dirigido a Nabucodonosor — ''Tú, oh rey'' (Dn 2:37) — y en el decreto de Artajerjes (Esd 7:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83393, 'spa', 'Asa (nombre propio)', 'Asa (nombre propio): El nombre propio Asa, llevado por el rey reformador de Judá y por un antepasado levita. Las 58 ocurrencias se refieren a estos dos individuos, con amplio predominio del rey. Notablemente, todas las lenguas consultadas — español, francés, alemán, inglés — transliteran el nombre de forma idéntica como ''Asa'', reflejo de su fonología breve y distintiva. Pasajes clave incluyen su ascenso al trono (1 Re 15:8-9) y sus reformas (1 Re 15:11-14; 2 Cr 14-16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83397, 'spa', 'Dano grave, desgracia', 'Dano serio, desgracia o lesion fatal que sobreviene a una persona. Las tres apariciones en Genesis (42:4, 38; 44:29) involucran el temor de Jacob de que un mal mortal ''sobrevenga'' (qarah/qara'') a Benjamin, evocando la perdida de Jose. Exodo 21:22-23 emplea el termino en derecho casuistico: si una mujer embarazada es golpeada y ''no hay אָסוֹן,'' basta una multa; pero si ocurre אָסוֹן, la pena se eleva a vida por vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83398, 'spa', 'Ataduras y prisión', 'Jueces 15:14 describe cómo las cuerdas en los brazos de Sansón se volvieron «como lino ardiendo» cuando el Espíritu vino sobre él. Eclesiastés 7:26 advierte que las manos de la mujer adúltera son «ataduras» que capturan al pecador. Jeremías 37:15 llama al lugar de encarcelamiento de Jeremías «la casa de las ataduras». El hebreo vincula la sujeción física con el confinamiento institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83399, 'spa', 'Banda y prisión', 'Daniel 4:15 y 4:23 describen la visión de Nabucodonosor de un tocón de árbol dejado «con una banda de hierro y bronce», simbolizando la restricción y humillación del rey durante su período de locura. Esdras 7:26 enumera posibles castigos por violar el decreto real, incluyendo la «prisión». Las bandas metálicas en Daniel sugieren tanto protección del tocón como limitación impuesta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83401, 'spa', 'Persona retenida en confinamiento físico o cautiverio, usado tanto para prisione', 'Persona retenida en confinamiento físico o cautiverio, usado tanto para prisioneros literales (los compañeros de celda de José en Gn 39:20, 22; Sansón moliendo en la prisión filistea, Jue 16:21, 25) como poéticamente para los aplastados por la opresión. En los Salmos, el prisionero se convierte en objeto de compasión divina (Sal 69:34; 79:11; 102:21), frecuentemente emparejado con ''hijos de muerte'' o ''los necesitados''. Zacarías 9:11 extiende la imagen a los ''prisioneros de esperanza''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83412, 'spa', 'Prisionero o cautivo', 'Prisionero, cautivo: quien está atado, confinado o capturado en guerra, a menudo en sentido colectivo. Isaías 42:7 asocia a los prisioneros con «los que habitan en tinieblas», presentando la cautividad como realidad tanto física como espiritual. Isaías 24:22 visualiza un juicio cósmico donde reyes son reunidos como presos en una fosa. En el Salmo 79:11, el gemido del prisionero (vinculado con H0603 אֲנָקָה) se convierte en vehículo de súplica ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83413, 'spa', 'Nombre propio, Asir', 'El nombre propio Asir, que significa ''prisionero'' o ''el atado.'' Identifica al menos a dos individuos: un descendiente levitico de Core que aparece en la genealogia de Exodo 6:24 y en la linea levitica extendida de 1 Cronicas 6:22-37, y posiblemente una figura en la genealogia davidica de 1 Cronicas 3:17. Las glosas multilingues transliteran uniformemente el nombre (esp. ''Asir,'' ing. ''Assir'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83417, 'spa', 'Esposa egipcia de José', 'Génesis 41:45 presenta a Asenat cuando Faraón la da a José como esposa, identificando a su padre como Potifera, sacerdote de On (Heliópolis). Génesis 41:50 señala que le dio a José dos hijos antes de los años de hambruna. Génesis 46:20 la incluye en el registro genealógico, marcando a Efraín y Manasés como sus hijos. Su nombre egipcio y linaje sacerdotal resaltan la plena integración de José en Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83418, 'spa', 'reunir, recoger', 'La acción transitiva básica del Qal de juntar personas, animales o cosecha en un mismo lugar. El árabe جمع y el coreano 모으다 confirman el significado nuclear de ''reunir''. Domina en contextos narrativos como reunir a los ancianos (Éx 3:16) o provisiones (Gn 6:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83419, 'spa', 'congregarse, reunirse', 'Nifal reflexivo/voz media: las personas se congregan o son reunidas como grupo. El árabe اجتمع (Forma VIII reflexiva) y el suajili kukusanyika (sufijo reflexivo -ika) reflejan con precisión este matiz de voz media. Véase Gn 29:3 donde los pastores se reúnen junto al pozo, o Éx 32:26 en la crisis del becerro de oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83422, 'spa', 'reunido con su pueblo', 'El distintivo eufemismo Nifal para la muerte: ser ''reunido con su pueblo'' o ancestros. El árabe انضمّ (''ser unido, agregado'') capta la metáfora relacional. La fórmula aparece en las muertes de Abraham (Gn 25:8), Ismael (Gn 25:17) y Jacob (Gn 49:33), siempre distinta de la sepultura, implicando reunión con los difuntos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83428, 'spa', 'barrer, consumir (Hifil)', 'Intensificación causativa Hifil que significa barrer o consumir por completo, presente en oráculos proféticos de juicio. Sofonías 1:2-3 emplea el infinitivo absoluto cognado para dar énfasis (''quitando quitaré''). El coreano 끝내리라 (''llevar a su fin'') capta la finalidad de este uso de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83429, 'spa', 'retaguardia (participio Piel)', 'El participio Piel funcionando como término técnico militar: la retaguardia que ''recoge'' a los rezagados al final de una columna en marcha. El árabe ساقَ y el suajili walinzi wa nyuma expresan este rol militar específico. Prominente en el orden de marcha del desierto (Nm 10:25) y la procesión de Jericó (Jos 6:9, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83441, 'spa', 'quitar, retirar', 'Un sentido extendido de quitar, retirar o apartar, aplicado a Dios quitando el oprobio (Gn 30:23), retirando su ira (Sal 85:3) o recogiendo una mano de la acción (1 S 14:19). El árabe نزع/رفع y el suajili ameondoa confirman el desplazamiento semántico de ''reunir'' a ''remover''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83453, 'spa', 'ser reunido intensivamente (Pual)', 'Pual pasivo intensivo: ser reunido o congregado con exhaustividad. El árabe يُجمَع (pasivo) refleja la forma. Se encuentra en contextos escatológicos como la reunión de prisioneros (Is 24:22) y el despojo de naciones (Zac 14:14), donde la voz pasiva subraya la totalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83459, 'spa', 'sanar, restaurar', 'Una raíz homográfica probablemente distinta que significa ''sanar, restaurar'', atestiguada exclusivamente en la narrativa de Naamán (2 R 5:3-11). El árabe يشفي y el suajili kumponya/ataponya traducen independientemente con vocabulario de sanación en lugar de reunión, respaldando con fuerza una entrada léxica separada. La Septuaginta lo traduce con θεραπεύω.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83549, 'spa', 'Asaf (nombre propio) — Nombre propio אָסָף (''recolector''), que se refiere princi', 'Asaf (nombre propio) — Nombre propio אָסָף (''recolector''), que se refiere principalmente al músico levita a quien David designó como cantor principal ante el arca (1 Cr 6:39; 16:5-7), acreditado con don profético (2 Cr 29:30) y la composición de los Salmos 50 y 73-83. Sus descendientes — los ''hijos de Asaf'' — formaron un gremio hereditario de cantores del templo activo desde el primer templo hasta la restauración postexílica (Esd 2:41; Neh 12:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83553, 'spa', 'Almacenes del templo', '1 Crónicas 26:15 asigna la suerte del almacén a los hijos de Obed-edom, ubicando estos depósitos cerca de la puerta sur del complejo del templo. 1 Crónicas 26:17 especifica turnos de guardia, con levitas apostados «junto al almacén» para proteger los bienes acumulados. Nehemías 12:25 menciona a porteros sirviendo «en los almacenes de las puertas», indicando múltiples instalaciones de almacenamiento alrededor del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83554, 'spa', 'Cosecha y recolección', 'Isaías 32:10 advierte que «la recolección no vendrá», una cosecha fallida que deja turbados a los confiados. Isaías 33:4 compara el saqueo militar con «la recolección de la langosta», imagen de una apropiación total que no deja nada atrás. Miqueas 7:1 usa un lamento en primera persona: «Soy como quien recoge frutos de verano», pero sin hallar ninguno, expresando esterilidad espiritual mediante metáfora agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83558, 'spa', 'Diligentemente, cabalmente', 'Denota esmero, diligencia y completitud en la ejecución de una acción, particularmente de edictos reales. Todas sus apariciones se encuentran en las secciones arameas de Esdras dentro de decretos gubernamentales persas. Tanto el español ''diligentemente'' como el inglés ''diligently'' convergen en la idea de ejecución cuidadosa y cabal, con un matiz secundario de urgencia presente en algunas interpretaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83560, 'spa', 'Obligar mediante un voto, juramento u obligación solemne — 11 ocurrencias concen', 'Obligar mediante un voto, juramento u obligación solemne — 11 ocurrencias concentradas en Números 30, el capítulo normativo sobre la fuerza vinculante de los votos femeninos. Una mujer ''se obliga a sí misma'' (Nm 30:3) y su padre o esposo puede anular lo que ''ata su alma'' (Nm 30:4-6). La extensión metafórica de las cuerdas físicas a la obligación legal es un fenómeno natural y translingüístico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83561, 'spa', 'Atar o ligar físicamente con cuerdas, sogas o grilletes — el sentido nuclear con', 'Atar o ligar físicamente con cuerdas, sogas o grilletes — el sentido nuclear con 30 ocurrencias. José ata a Simeón (Gn 42:24), Jacob ata el pollino de su asna a la vid (Gn 49:11), y los filisteos atan a Sansón con sogas nuevas (Jue 15:13) y con cadenas de bronce (Jue 16:21). El árabe asara y el acadio asāru conservan este mismo significado de sujeción física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83564, 'spa', 'Estar atado, encadenado o sujeto con ligaduras — 16 ocurrencias en formas pasiva', 'Estar atado, encadenado o sujeto con ligaduras — 16 ocurrencias en formas pasivas (participio pasivo Qal), Nifal y Pual. José queda ''atado'' en la cárcel (Gn 39:20), el copero y el panadero están ''presos'' (Gn 40:5), y Sansón pregunta cómo podría ser ''atado'' para probar su fuerza (Jue 16:6). La distinción con el sentido 1 es de voz: el sujeto recibe la acción en lugar de ejecutarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83565, 'spa', 'Participio pasivo sustantivado', 'Participio pasivo sustantivado: un prisionero, cautivo o encadenado — 8 ocurrencias donde אָסוּר funciona como sustantivo. Los oficiales del faraón están en la ''casa de los presos'' con los ''encadenados'' (Gn 39:20; 40:3), Sansón muele grano como ''prisionero'' (Jue 16:21) y Dios ''libera a los cautivos'' (Sal 146:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83567, 'spa', 'Enganchar, uncir o atar animales a un vehículo — 7 ocurrencias en contextos mili', 'Enganchar, uncir o atar animales a un vehículo — 7 ocurrencias en contextos militares y agrícolas. José engancha su carro para recibir a Jacob (Gn 46:29), el faraón engancha su carro para la persecución (Éx 14:6) y Elías dice a Acab que ''enganche'' (1 Re 18:44). El español ''enganchar'' y el inglés ''harness'' seleccionan un vocabulario especializado distinto del genérico ''atar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83606, 'spa', 'Una única ocurrencia ambigua en 1 Re 20', 'Una única ocurrencia ambigua en 1 Re 20:14 donde el texto hebreo y las versiones divergen en su interpretación. El español ''comenzará'' y el inglés ''will begin'' sugieren una lectura de אָסַר como iniciar una batalla, posiblemente una corrupción textual o un uso idiomático raro que significa ''trabar combate''. Las versiones en árabe y coreano también reflejan incertidumbre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83607, 'spa', 'Obligación vinculante autoimpuesta o voto restrictivo, específicamente un compro', 'Obligación vinculante autoimpuesta o voto restrictivo, específicamente un compromiso de abstenerse o negarse algo a sí mismo. Se usa exclusivamente en Números 30:2-14 dentro de la legislación que rige los votos de las mujeres. El texto lo empareja con néder (נֶדֶר) como categoría complementaria: el néder promete una acción positiva, mientras que el isar promete abnegación. Un padre puede anular el isar de su hija soltera el día que lo escucha, y un esposo puede hacer lo mismo con el de su esposa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83612, 'spa', 'Interdicto, prohibición real', 'Un interdicto formal y legalmente vinculante, o prohibición emitida por autoridad real. Las siete apariciones se encuentran en Daniel 6:7-15, describiendo el decreto que prohibía orar a cualquier otro que no fuera el rey Darío durante treinta días. El español ''prohibición'' y el inglés ''interdict'' capturan la fuerza legal restrictiva, mientras que la etimología preserva la conexión con la raíz אסר (''atar'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83614, 'spa', 'Esar-hadón (nombre propio)', 'Nombre propio del rey asirio Esar-hadón (אֵסַרְחַדֹּן, acadio Aššur-aḫu-iddina, ''Asur ha dado un hermano''), quien reinó del 681 al 669 a.C. Sucedió a su padre Senaquerib tras el asesinato de este por sus propios hijos (2 R 19:37 = Is 37:38), cumpliendo la profecía de juicio divino de Isaías. En Esdras 4:2, los colonos samaritanos invocan a Esar-hadón como el rey que los reasentó en la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83618, 'spa', 'Ester (nombre propio)', 'Ester (nombre propio): La reina judía de Persia que salvó a su pueblo del complot genocida de Amán. Su nombre puede derivar del persa ''estrella'' o de la diosa Ishtar; su nombre hebreo Hadasa significa ''mirto'' (Est 2:7). Las 55 ocurrencias se encuentran exclusivamente en el Libro de Ester, desde su coronación (Est 2:17) hasta su valiente intervención (Est 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83622, 'spa', 'Madera, viga', 'Madera o madero como material de construccion y como sustancia de objetos tallados. En los pasajes de Esdras (5:8; 6:4, 11) la palabra se refiere a madera labrada y vigas estructurales para la reconstruccion del templo bajo el decreto de Dario. En Daniel 5:4 y 5:23 se desplaza hacia la composicion material de los idolos: dioses ''de oro, plata, bronce, hierro, madera y piedra.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83623, 'spa', 'ciertamente, en verdad', 'Uso enfático-afirmativo: ''ciertamente, en verdad, sí''. Con 51 ocurrencias, este sentido encabeza declaraciones contundentes, especialmente en poesía. Sal 16:6-9 acumula cuatro cláusulas con אַף para construir un crescendo de alabanza. Las traducciones lo vierten como ''indeed/ciertamente/aussi/ja'', captando el refuerzo retórico más que la mera adición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83624, 'spa', 'también, además', 'Uso aditivo-inclusivo: ''también''. Con 44 ocurrencias, es la función conjuntiva simple, frecuentemente como וְאַף (''y también''). Levítico 26 lo emplea repetidamente para acumular consecuencias del pacto. BDB señala que גַּם es más común en prosa para esta función, lo que hace de אַף el aditivo más elevado o marcado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83628, 'spa', 'cuánto más/menos', 'La partícula a fortiori: ''cuánto más'' o ''cuánto menos'', típicamente en el patrón אַף כִּי. Impulsa 22 argumentos de menor a mayor: si los hombres de David temían en Judá, ''cuánto más'' en Keila (1 S 23:3). Español ''cuánto más/menos'' y alemán ''wie viel mehr'' muestran que los traductores reconocen la estructura de escalamiento lógico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83629, 'spa', 'aun (escalar, intensivo)', 'Uso escalar-intensivo: ''aun'', marcando un caso extremo o inesperado. Siete ocurrencias destacan algo más allá de lo esperado. Lv 26:44 asegura que ''aun'' en el exilio Dios no rechazará del todo a Israel. Job 14:3 pregunta si Dios llevaría ''aun'' a una criatura tan frágil a juicio. Alemán ''sogar'' y español ''aun'' precisan esta fuerza escalar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83632, 'spa', '¿acaso? (interrogativo enfático)', 'Uso interrogativo-enfático en preguntas: ''¿acaso? ¿de veras?'' Seis ocurrencias aparecen con la partícula interrogativa הֲ, expresando sorpresa o desafío. Gn 18:13 pregunta ''¿De veras daré a luz?'' y Job 40:8 desafía ''¿Acaso invalidarás mi juicio?'' La partícula intensifica la fuerza retórica de la pregunta más allá de la simple interrogación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83635, 'spa', 'además, es más', 'Uso como conector discursivo: ''además, es más'', añadiendo un punto suplementario que refuerza el argumento. Tres ocurrencias (1 Cr 16:30; Est 5:12; Ez 23:40) emplean אַף para agregar un detalle culminante o adicional. Español ''además'' e inglés ''moreover'' señalan esta función conectiva-aditiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83640, 'spa', 'sin embargo (concesivo)', 'Un único uso concesivo en Sal 44:10 traducido como ''sin embargo'' en español, donde la partícula introduce un giro sorpresivo: a pesar de todas las afirmaciones precedentes, Dios ha rechazado a su pueblo. Este raro matiz adversativo muestra que אַף puede pivotar de la adición al contraste cuando el contexto lo exige.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83654, 'spa', 'Conjunción aditiva', 'Conjunción aditiva «también, aun, además» en arameo bíblico, siempre emparejada con waw (וְאַף). En Esdras 5:10 y 5:14 añade información complementaria en correspondencia oficial de la era persa: «y también les preguntamos sus nombres» y «y también los utensilios». Esdras 6:5 la emplea para extender el decreto de Ciro a los utensilios del templo. Daniel 6:22 la usa para una afirmación enfática de inocencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83655, 'spa', 'ira, furor (general)', 'El sentido metafórico dominante: ira, furor, cólera, con 210 de 276 ocurrencias. La imagen de narices dilatadas y aliento ardiente está completamente abstraída en la mayoría de contextos. La frase חֲרוֹן אַף (''ardor de ira'') aparece predominantemente referida a la ira divina (Éx 32:12; Nm 25:4), aunque la ira humana también se registra (Gn 30:2; 49:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83666, 'spa', 'tardo para la ira', 'La expresión idiomática fija אֶרֶךְ אַפַּיִם — ''tardo para la ira'', literalmente ''largo de narices'' — con 14 ocurrencias en contextos litúrgicos que describen un atributo divino. Proclamada en Sinaí en la autorrevelación de Dios (Éx 34:6), repetida en Cades (Nm 14:18), en Nehemías (9:17) y a lo largo del Salterio (86:15; 103:8; 145:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83668, 'spa', 'rostro, semblante', 'La forma dual אַפַּיִם usada para ''rostro'' o ''semblante'', con 21 ocurrencias concentradas en fórmulas de postración (נפל על אַפַּיִם, ''cayó sobre su rostro''). La dualidad se extiende de las narices al rostro completo. Domina en gestos de reverencia: Abraham ante los hititas (Gn 23:7), los hermanos de José ante él (Gn 42:6), Balaam ante el ángel (Nm 22:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83670, 'spa', 'nariz, narices', 'El sentido anatómico literal: nariz, narices u hocico, con 30 ocurrencias que preservan la referencia corporal original. Dios sopla en las narices de Adán (Gn 2:7), el aliento de vida está en las narices de toda carne (Gn 7:22) y Rebeca recibe un anillo en su nariz (Gn 24:47). El dual אַפַּיִם a veces especifica las dos fosas nasales explícitamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83699, 'spa', 'doble (porción)', 'Una única ocurrencia disputada en 1 S 1:5 donde אַפַּיִם parece significar ''doble'' (una porción doble). La evidencia multilingüe — inglés ''double'', español ''doble'', francés ''double'' — traduce una cantidad y no nariz, rostro o ira. Algunos estudiosos reinterpretan esto como una raíz diferente, pero la lectura del TM se mantiene como hapax en sentido distributivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83738, 'spa', 'Banda sacerdotal y revestimiento', 'En Éxodo 28:8 y 39:5 se describe «la banda hábilmente tejida del efod» que aseguraba la vestidura sagrada del sumo sacerdote, confeccionada con los mismos materiales: oro, azul, púrpura, carmesí y lino fino. Isaías 30:22 condena la idolatría mencionando «la cobertura de tus imágenes fundidas de oro». El vínculo entre vestiduras sacerdotales e ídolos revestidos revela cómo lo sagrado puede corromperse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83740, 'spa', 'Participio Qal usado como sustantivo que significa ''panadero'' — un profesional q', 'Participio Qal usado como sustantivo que significa ''panadero'' — un profesional que hornea pan. Central en el relato de José en Génesis 40, donde el jefe de los panaderos (sar ha-ofim) aparece junto al copero. También en 1 Samuel 8:13 (mujeres como panaderas) y Oseas 7:4-6 donde el horno del panadero se convierte en metáfora política.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83742, 'spa', 'Forma pasiva del tronco Nifal', 'Forma pasiva del tronco Nifal: ''ser horneado,'' con el alimento como sujeto gramatical en vez de la persona que hornea. Se limita a la legislación levítica (Lv 6:17, 7:9, 23:17) donde especifica cómo deben prepararse las ofrendas. Las traducciones recurren a perífrasis pasivas, subrayando la distinción de voz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83743, 'spa', 'Verbo finito Qal activo que significa ''hornear'' — preparar alimento mediante cal', 'Verbo finito Qal activo que significa ''hornear'' — preparar alimento mediante calor en un horno o sobre fuego. Abarca el horneado cotidiano de pan (Is 44:15, 19), el horneado de emergencia de panes sin levadura (Gn 19:3, Éx 12:39), la preparación del maná en el desierto (Éx 16:23) y la preparación del pan cultual (Lv 24:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83759, 'spa', 'Partícula enclítica enfática que intensifica enunciados interrogativos o inferen', 'Partícula enclítica enfática que intensifica enunciados interrogativos o inferenciales. Se combina típicamente con palabras interrogativas: מִי אֵפוֹא (''¿quién entonces?'', Gn 27:33), אַיֵּה אֵפוֹא (''¿dónde entonces?'', Jue 9:38; Isa 19:12; Job 17:15), וּבַמֶּה יִוָּדַע אֵפוֹא (''¿en qué se conocerá entonces?'', Éx 33:16). También se usa en contextos deliberativos (Gn 43:11). Funcionalmente equivale al griego ἆρα/ποτέ y al latín tandem.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83763, 'spa', 'Efod (vestidura sacerdotal)', 'Efod (vestidura sacerdotal): Una vestidura sacerdotal de elaboración variable: en su forma más suntuosa, la pieza que cubría los hombros del sumo sacerdote, tejida en oro, azul, púrpura y escarlata, con piedras de ónice en los hombros (Éx 28:6-12; 39:2-7), que sostenía el pectoral del juicio con el Urim y el Tumim; en su forma más sencilla, un efod de lino vestido por sacerdotes comunes (1 Sam 22:18) y por Samuel y David en contextos de adoración (1 Sam 2:18; 2 Sam 6:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83774, 'spa', 'Cauce natural, canal, lecho de arroyo, wadi o barranco por donde fluye o fluyó e', 'Cauce natural, canal, lecho de arroyo, wadi o barranco por donde fluye o fluyó el agua. Este sentido dominante (16 ocurrencias) se concentra en textos poéticos y proféticos: los cauces del mar expuestos ante la reprensión de Dios (2 S 22:16; Sal 18:15), el ciervo que anhela los arroyos de agua (Sal 42:1), los wadis del Néguev como imagen de restauración (Sal 126:4), y los barrancos y valles de Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83779, 'spa', 'Tubo, conducto o hilera cilíndrica — la metáfora del canal extendida a estructur', 'Tubo, conducto o hilera cilíndrica — la metáfora del canal extendida a estructuras físicas no acuáticas. Dos ocurrencias en las descripciones de grandes bestias en Job: los huesos del hipopótamo son ''tubos de bronce'' (Job 40:18), y las escamas del cocodrilo forman ''canales de escudos'' bien ajustados (Job 41:15). El español ''tubos'' y ''canales'' preservan la imagen de formas cilíndricas huecas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (83783, 'spa', 'Uno fuerte o poderoso — probablemente de una raíz relacionada אָפִיק que signifi', 'Uno fuerte o poderoso — probablemente de una raíz relacionada אָפִיק que significa ''firme, fuerte'', y no del significado de cauce. Solo 1 ocurrencia: Job 12:21, donde Dios ''derrama menosprecio sobre los fuertes''. Algunos eruditos lo conectan con cognados arameos que significan ''fuerte'', sugiriendo una superposición homonímica con el sentido de canal.');